from pathlib import Path
import json, re

BASE = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent
ALL = ["Stone-Zsela", "Stevens", "O'Connor", "Scalia", "Kennedy", "Souter", "Thomas", "Ginsburg", "Breyer"]
SEVEN = [j for j in ALL if j not in ["Scalia", "Thomas"]]
ROSTER = ", ".join(ALL[:-1]) + " and " + ALL[-1]
R7 = ", ".join(SEVEN[:-1]) + " and " + SEVEN[-1]
RECON = (BASE / 'freeze/OT_2002CHUNK9_C_RECONCILED.md').read_text(encoding='utf-8')
FINAL, INITIAL = RECON.split('## Verbatim preserved initial commitments', 1)
STONE = (BASE / 'runtime/OT_2002CHUNK9_C_STONE.md').read_text(encoding='utf-8')

def section(text, n):
    m = re.search(r'^## '+str(n)+r'\. .*?(?=^## \d+\.|^## (?:Verification|Scope completion)|\Z)', text, re.M|re.S)
    assert m, n
    return m.group(0).strip()

def h(title, rule, authority, explanation, treatment, limits=''):
    s = f'### {title}\n\n**Holding and operative rule:** {rule}\n\n**Authority:** {authority}\n\n**Controlling explanation:** {explanation}\n\n**Precedent treatment:** {treatment}'
    if limits: s += '\n\n**Operative qualifications:** '+limits
    assert len(explanation.split()) <= 350, title
    return s

cases=[]

mad_h='\n\n'.join([
h('I. Deliberate factual deception may be proved without regulating fundraising percentages',
  'The First Amendment permits an action against a charitable fundraiser for material factual representations knowingly used to deceive donors about the use of their contributions. High fundraising costs or failure to volunteer the fee percentage alone cannot establish fraud; the State must prove the independently identified representation, its materially false contextual meaning, intentional deception and the remaining requirements of its actual cause and remedy.',
  'Part I of the opinion of the Court; all nine Justices directly join: '+ROSTER+'.',
  'Schaumburg, Munson and Riley protect charitable solicitation from percentage restrictions and compelled fee disclosures while preserving genuine antifraud enforcement. A charity may spend money communicating its cause, and a statement that a contribution helps the charity does not become false merely because expenses consume most receipts. Information and advocacy undertaken during solicitation may themselves perform charitable work. The Court therefore rejects both a percentage presumption and a general duty to announce unfavorable financial information.\n\nThe alleged promises that at least ninety percent would go to veterans and that contributions would pay no labor expenses because all workers were volunteers present a different question. Their meaning and truth can be tested independently of whether an eighty-five-percent fee was reasonable. The contractual allocation may be evidence contradicting a specific promise; it cannot supply a promise that was never made. Requiring the State to establish actual, deliberate factual deception answers the claim that fraud litigation necessarily imposes the same restraint as a forbidden fee cap. Edenfield recognizes the distinct treatment of deception, but does not reduce charitable advocacy to ordinary commercial advertising. These particular allegations permit the fraud litigation to proceed.',
  'Schaumburg, Munson and Riley are applied to preserve protected solicitation and the fee/disclosure boundary while permitting genuine fraud enforcement. Edenfield supplies the deception distinction at its own scope.'),
h('II. Each restored cause retains its own proof and remedial requirements',
  'For the intentional common-law fraud restored here, Illinois must establish by clear and convincing evidence a materially false factual representation, knowledge of falsity, intent to mislead, successful deception through justifiable reliance, and resulting damage. A distinct public statutory theory must satisfy its own elements and evidentiary burden and the First Amendment boundary in Part I; it cannot evade that boundary by relabeling a fee cap.',
  'Part II of the opinion of the Court; all nine Justices directly join.',
  'Hofmann supplies Illinois\'s rule that fraud is not presumed and requires clear and convincing proof. Witt identifies the factual falsity, knowledge, intended inducement, justifiable reliance and damage required for common-law fraud, and distinguishes actual deceptive intent from conduct violating a different duty. Those demanding requirements keep the burden on Illinois and protect truthful fundraising while allowing proof of the deliberate deception pleaded here.\n\nThe complaint invokes common-law and statutory causes. Neither Witt\'s disciplinary burden nor the elements of a private common-law action establish every requirement of a public consumer-protection cause. The lower court must identify the invoked theory and apply its actual law, including its culpability, causation, injury and remedy requirements. The clear-and-convincing rule stated here governs the intentional fraud at issue; it is not announced as a universal constitutional burden for all statutory enforcement. Reversal removes the constitutional dismissal of sufficiently pleaded affirmative deception. The State must then prove its claims under these rules, and any injunction must address established deception rather than lawful advocacy or the fee level itself.',
  'Hofmann v. Hofmann, 94 Ill. 2d 205, 222–225 (1983), supplies the common-law proof burden. In re Witt, 145 Ill. 2d 380, 390–391, 397 (1991), supplies the fraud elements and deliberate-intent distinction without supplying a universal statutory burden.')])

cases.append(dict(n=111,case='Illinois ex rel. Madigan v. Telemarketing Associates, Inc.',date='2003-05-05',file='Illinois-ex-rel-Madigan-v-Telemarketing-Associates-Inc_merits_2003-05-05.md',dockets='No. 01-1806; 538 U.S. 600',result='Reversed and remanded, 9–0, on the affirmative-fraud claims; stipulated dismissals remain effective.',
event='Merits decision, May 5, 2003. Argued March 3, 2003. On writ of certiorari to the Supreme Court of Illinois. The question is whether the First Amendment bars an action alleging deliberately false factual representations about charitable donations when professional fundraisers retain eighty-five percent of receipts. The Illinois Supreme Court affirmed dismissal as an impermissible percentage restriction. Illinois seeks reinstatement of its fraud claims.',
facts='VietNow retained professional fundraisers under Illinois contracts leaving fifteen percent of gross receipts to the charity. The complaint and attached affidavits allege promises of identified veterans services, a statement that at least ninety percent went to veterans, and a statement that labor consumed none of the contributions because participants were volunteers. Those are allegations accepted for review of the dismissal, not findings of falsity or culpability. The parties stipulated to dismissal of the other remaining claims.',
stone='The approved supplement supports reversal of sufficiently pleaded affirmative deception, the express fee/nondisclosure boundary, State-borne clear-and-convincing proof for the intentional fraud at issue, and independent requirements for other statutory theories and remedies. Stone joins the full common opinion. Its separate common-law and statutory treatment is faithful to his express source-specific qualification. No standing fallback is used and no conditional alternative is needed.',
compat='All eight frozen M1–M3 commitments and their proof qualification match Parts I–II. Scalia and Thomas require the express sentence that a general promise of charitable help is not false solely because of high legitimate expenses; Part I supplies it. The other six likewise preserve solicitation and State-borne proof. Stone adopts those same grounds. The full opinion answers the actual objections; there is no remaining substantive separate-writing function. No commitment, fact or remedy was changed after reconciliation.',
judgment='**Reversed and remanded, 9–0.**\n\n**Supporting:** '+ROSTER+'.\n\nThe constitutional dismissal of sufficiently pleaded affirmative-fraud claims is reversed. Liability based solely on the retained percentage or silence about it remains unavailable. The stipulated dismissal of the other claims remains effective. Further proceedings apply each surviving Illinois cause and its applicable proof and remedy requirements.',
topology='__LEAD_AUTHOR__ delivers the opinion of the Court, joined in full by __LEAD_JOINERS__. All nine join Parts I–II.',
holdings=mad_h,
precedent='Schaumburg, Munson and Riley retain their protection against percentage restrictions and compulsory fee disclosure; the deliberate-fraud route remains available. Edenfield preserves the distinction between truthful expression and deception without diminishing charitable advocacy\'s protection. Hofmann and Witt govern the described Illinois common-law fraud requirements, with distinct statutory causes retaining their own law.',
law='Charitable fundraisers remain protected against liability inferred from fundraising costs or nondisclosure alone. A State may prove deliberate material factual deception about contributions under the applicable cause of action. The operative inquiry concerns the actual representation and proof of deception, with financial allocation usable as evidence of an independently established false representation.',
separate='',procedure='The case returns to the Illinois courts for adjudication of the restored affirmative-fraud claims under Parts I–II. Those courts identify the actual theories, determine their required proof and causal predicates, and award any authorized relief on the established violation.',
sources='Illinois ex rel. Madigan v. Telemarketing Associates, Inc., No. 01-1806, 538 U.S. 600; judgment below, 198 Ill. 2d 345, 763 N.E.2d 289. Schaumburg v. Citizens for a Better Environment, 444 U.S. 620; Secretary of State of Maryland v. Joseph H. Munson Co., 467 U.S. 947; Riley v. National Federation of the Blind, 487 U.S. 781; Edenfield v. Fane, 507 U.S. 761. Hofmann v. Hofmann, 94 Ill. 2d 205; In re Witt, 145 Ill. 2d 380. The pleaded statements and fee arrangements remain subject to proof.',
negative='The fee/nondisclosure exclusion is the adopted constitutional limit and responds to the litigated fee-cap theory (iv). The stipulated dismissals state surviving judgments (iii). Distinct cause-specific proof requirements and the absence of a universal statutory burden are express join conditions needed to prevent misreading the common-law rule (iv). The injunction boundary states an adopted remedy limit (iv). Stock denials of damages, liability, new trial rights and industry-wide relief were omitted.',
source_map='The frozen validated C neutral packet and control-extracted record recitations establish the argument date, lower judgment, contractual allocation, specific allegations and stipulated dismissal. The frozen reconciled Madigan section verifies the complete historical opinion and concurrence, and Hofmann/Witt proof distinctions. The C focused Edenfield copy and Riley discussion supply date-eligible law. Original unrecovered filings are not represented as read.',
eligible=ALL,full=ALL,components=[dict(name='Affirmative-fraud dismissal reversed and remanded subject to the fee/nondisclosure boundary',supporting=ALL,opposing=[])]))

kaupp_h='\n\n'.join([
h('I. The nighttime compelled removal was an arrest',
  'An encounter is a seizure when the complete circumstances communicate that a reasonable person could not decline the officers\' request or terminate the encounter. The coordinated nighttime removal of Kaupp from his bedroom in handcuffs, underwear and bare feet for station-house interrogation was an arrest rather than voluntary cooperation; Texas\'s conceded absence of probable cause makes that arrest unlawful.',
  'The per curiam opinion; all nine Justices directly join: '+ROSTER+'.',
  'Mendenhall and Bostick require assessment of the entire communicated encounter. Dunaway and Hayes require probable cause for compulsory station-house detention of this kind. Several officers awakened the seventeen-year-old at approximately three in the morning, announced that they needed to talk, restrained him and transported him away. His brief assent and lack of resistance in those circumstances show submission, not a choice to accompany them. His father\'s permission to enter did not authorize the son\'s arrest.\n\nTexas\'s routine use of handcuffs during transportation explains an asserted practice but does not change what this encounter communicated. Removing the restraints later does not make the preceding removal consensual. The Court evaluates these circumstances together; no isolated characteristic substitutes for the complete inquiry. The eventual development of grounds after the statement cannot authorize an arrest already made. The state appellate court therefore erred in treating the initial custody as consensual.',
  'Mendenhall and Bostick supply the objective whole-encounter test. Dunaway and Hayes govern compulsory station-house investigation. Robinette preserves the distinct questions of voluntary cooperation and unlawful restraint.'),
h('II. Texas must establish a genuine causal break before using the resulting statement',
  'After an unlawful arrest and its causal connection to a statement are shown, the State bears the burden of establishing attenuation, considering temporal proximity, genuine intervening circumstances, the purpose and flagrancy of the unlawful conduct, and warnings. On the record presented Kaupp\'s statement must be suppressed; on remand Texas may identify already-available testimony not disclosed in the record before this Court only if it can carry that burden despite the continuous custody and planned interrogation shown here.',
  'The per curiam opinion; all nine Justices directly join.',
  'Brown separates Fifth Amendment voluntariness from the Fourth Amendment question whether an unlawful arrest produced the statement. Dunaway applies that distinction to investigative custody. The brief stop at the discovery site, removal of handcuffs at headquarters and administration of warnings were successive steps in the same planned interrogation. The statement followed shortly after questioning began. These circumstances provide no genuine intervening event; warnings alone cannot carry Texas\'s burden.\n\nThe remand permits the state court to evaluate identified, already-available testimony not disclosed here if it is sufficiently weighty under Brown. It presumes no such testimony and supplies no automatic reopening of proof to create an intervening event. If Texas cannot establish the required break, the statement must be excluded. The state court then resolves the consequences for the conviction. If a properly preserved harmless-error ground is available, Texas must establish beyond a reasonable doubt, from the actual trial record, that admission did not contribute to the verdict; otherwise the affected conviction must be set aside for lawful further proceedings.',
  'Brown and Dunaway govern the causal exclusion and burden. Robinette preserves attenuation as distinct from voluntariness. Dickerson preserves Miranda as a separate safeguard. Chapman supplies the direct-review harmless-error standard, concerned with the actual verdict rather than a hypothetical untainted prosecution.')])

cases.append(dict(n=112,case='Kaupp v. Texas',date='2003-05-05',file='Kaupp-v-Texas_summary-merits_2003-05-05.md',dockets='No. 02-5636; 538 U.S. 626; Texas appellate No. 14-00-00128-CR',result='Judgment vacated and case remanded, 9–0, by summary per curiam decision.',
event='Summary merits decision, May 5, 2003, on the submitted papers without oral argument. On review of the Texas Court of Appeals, Fourteenth District, after the Court of Criminal Appeals denied discretionary review. The questions are whether the nighttime home removal was an arrest without probable cause and whether the resulting statement may be admitted under the governing attenuation rule.',
facts='After a fourteen-year-old girl was killed, her half brother implicated Kaupp. Detectives unsuccessfully sought a questioning warrant through the district attorney, believing they lacked probable cause for an ordinary arrest warrant. At about three in the morning, several officers entered with Kaupp\'s father\'s permission, awakened the seventeen-year-old, handcuffed him and took him without shoes and in underwear to a patrol car. They stopped for five to ten minutes at the discovery site, then took him to headquarters, removed handcuffs and gave warnings. Ten to fifteen minutes into interrogation he admitted a role but not infliction of the fatal wound. His suppression motion failed; he was convicted and sentenced to fifty-five years. Texas disclaims probable cause at initial removal. The published recitation establishes no material intervening event.',
stone='Stone expressly supports vacatur, unlawful-arrest analysis, Texas\'s Brown burden, suppression unless preserved existing evidence establishes attenuation, and the actual-verdict harmless-error standard. The final K3-R proviso fits his approved prohibition on an unsupported evidentiary reopening. No standing fallback is used. A prohibition on ordering an insufficiency acquittal is satisfied by the actual vacatur and lawful remand without a stock public disclaimer.',
compat='All eight final K1, K2 and K3-R commitments directly join both holdings and the bounded remedy. Stone independently adopts them. The original K3 is preserved only as provisional provenance in the copied audit; K3-R controls, allowing sufficiently weighty already-available testimony without assuming that it exists or authorizing invented new proof. The direct-review harmless-error formulation applies ordinary law and Stone\'s express position; it changes no non-Stone commitment. Per curiam summary review is selected from the supplied posture before any count; no separate grant event or certiorari poll is inferred.',
judgment='**Vacated and remanded, 9–0.**\n\n**Supporting:** '+ROSTER+'.\n\nThe judgment sustaining Kaupp\'s conviction on a consensual-removal rationale is vacated. The statement must be suppressed unless Texas establishes attenuation through sufficiently weighty already-available testimony not disclosed in the record before this Court. The state courts then determine the conviction\'s lawful consequences under Part II.',
topology='Per curiam. All nine Justices join the entire opinion and its bounded remand.',holdings=kaupp_h,
precedent='Mendenhall and Bostick are applied to the complete encounter; Dunaway and Hayes govern the compelled station-house investigation. Brown and Robinette preserve a separate causal inquiry after illegality. Dickerson\'s warning safeguard does not displace that inquiry. Chapman governs any properly available direct-review harmless-error issue.',
law='The objective seizure and attenuation rules remain controlling. This coordinated, restrained nighttime removal was an unlawful arrest; neither cooperation in that custody nor customary handcuffing establishes consent. The shown interrogation sequence supplies no sufficient causal break. The limited existing-testimony proviso preserves Texas\'s burden under Brown.',
separate='',procedure='On remand the state court must identify any already-available testimony asserted to establish attenuation and apply all material Brown factors. If Texas fails its burden, the court must exclude the statement and resolve the conviction under the governing preserved harmless-error and further-proceedings rules.',
sources='Kaupp v. Texas, No. 02-5636, 538 U.S. 626; Texas appellate No. 14-00-00128-CR. United States v. Mendenhall, 446 U.S. 544; Florida v. Bostick, 501 U.S. 429; Dunaway v. New York, 442 U.S. 200; Hayes v. Florida, 470 U.S. 811; Brown v. Illinois, 422 U.S. 590; Chapman v. California, 386 U.S. 18. Ohio v. Robinette, decided November 18, 1996; Dickerson v. United States, decided June 26, 2000. The record before the Court describes continuous custody and the stated interrogation sequence; the remand addresses only identified existing testimony bearing on attenuation.',
negative='The no-automatic-reopening sentence is the adopted boundary of the unusual existing-testimony proviso (iv), not boilerplate. Warnings alone are insufficient is an affirmative causal limit responding to Texas (iv). The vacated appellate judgment and conditional remaining conviction work state operative status (iii). No acquittal, civil damages, immunity, universal juvenile rule or routine transport disclaimer appears in the five controlled blocks.',
source_map='Frozen C neutral record recitation supplies the encounter and state proceedings. Final reconciled K3-R supersedes the initial K3 breadth and records full Cornell/official-opinion verification. C Rules supplies Robinette, Dickerson and review rules; C Current Focus supplies Wheat\'s pre-seizure and separate causal-exception boundaries. The arrest-warrant distinction is preserved; no judicial rejection of an ordinary probable-cause warrant is invented.',
eligible=[],full=[],components=[dict(name='Conviction judgment vacated and remanded under the unlawful-arrest and bounded attenuation ruling',supporting=ALL,opposing=[])],countable=False))

rene_h='\n\n'.join([
h('I. Same-sex harassment requires a supported inference of discrimination because of sex',
  'Title VII covers same-sex harassment when competent direct or circumstantial evidence establishes discrimination because of sex; sexual content, contact or severity alone does not conclusively establish that cause. A claimant\'s attribution of the abuse to hostility toward his sexual orientation is evidence, not a binding legal concession excluding his pleaded sex-harassment claim, and an actual opposite-sex coworker or proof of sexual desire is unnecessary.',
  'Part I of the opinion of the Court; all nine Justices directly join: '+ROSTER+'.',
  'Oncale supplies both same-sex coverage and the independent statutory causal requirement. An all-male work unit cannot be exempt simply because no female comparator works there. Equally, the sexual form of offensive conduct cannot replace evidence of why it occurred. Possible direct and circumstantial proof is not confined to a mandatory checklist.\n\nRene\'s administrative charge identified his male sex and his complaint alleged sexual harassment. His testimony about orientation may bear on the attackers\' reasons, but a witness\'s legal description does not itself abandon that pleaded claim. The evidence must be evaluated under Rule 56, preserving reasonable favorable inferences without resolving credibility. Brown v. Polk County confirms that one real explanation need not exclude a discriminatory one; its distinct pre-1991 direct-evidence burden shift is not required to decide this motion. The preserved sex-harassment claim supplies the question before the Court. An independent cause for every orientation-based employment action lies outside the question and is not established as separately preserved here.',
  'Oncale is applied without its sexual-content limit being diluted. Brown v. Polk County supplies the nonexclusive character of possible motives at its own statutory scope. Nabozny preserves separate sex and orientation analysis and favorable-inference discipline in its distinct equal-protection setting.'),
h('II. Rene\'s combined evidence permits the required inference',
  'The combination of repeated targeted sexual touching, associated humiliation and treatment described as directed toward a woman permits a reasonable inference that Rene suffered discrimination because of sex. Because that inference arises from the whole preserved record, the employer is not entitled to summary judgment on the asserted absence of sex causation, although the evidence does not compel the inference.',
  'Part II of the opinion of the Court; '+R7+' directly join. Scalia and Thomas dissent from this application.',
  'Rene described nearly daily abuse over two years: sexualized names, gestures, pictures and gifts, repeated grabbing of his crotch, and fingers pushed into his anus through his clothing. His description of feminizing treatment gives the physical conduct a contextual significance beyond its severity alone. A reasonable factfinder could read the targeted intrusions and associated humiliation together as sex-directed treatment. His orientation explanation does not require the court to draw the opposite inference against him on MGM\'s motion.\n\nThe dissent regards the woman-treatment description as only a description of sexual form. That is a possible reading, but the surrounding pattern also permits the sex-directed inference. Rule 56 does not permit selection of the employer\'s reading when a reasonable contrary inference rests on the evidence. The Court sustains the appellate remand on that ground, rejecting its lead opinion\'s suggestion that severe unwelcome sexual touching necessarily proves sex causation. This is an application of the preserved claim, not creation of an appellate stereotyping claim.',
  'Oncale supplies the controlling causal distinction and permits the contextual inference without a per se touching rule. Harris supplies contextual assessment while keeping cause distinct from environmental severity.'),
h('III. Further proceedings apply the remaining environment, attribution and remedy requirements',
  'Rene must prove by a preponderance the conduct, prohibited cause, an objectively and subjectively hostile environment sufficiently severe or pervasive to alter employment conditions, and employer responsibility. Under the actual-authority route he must prove that delegated supervisory authority materially aided creation or maintenance of that environment; rank alone is insufficient, while negligence remains a distinct route and compensatory relief requires its own proved injury.',
  'Part III of the opinion of the Court; '+R7+' directly join.',
  'Harris directs consideration of frequency, severity, physical threat or humiliation and unreasonable interference with work, without making any one consideration indispensable. Psychiatric injury, treatment and lost productivity are not additional liability elements. Oncale, Faragher and Ellerth keep that inquiry separate from employer attribution. Actual delegated power must materially aid the unlawful environment; higher-management notice, a completed employment action and tangible economic loss are not invariably necessary to that route. Any negligence ground requires its own proof.\n\nThe case returns for ordinary adjudication of those elements and the conditions of the relief sought. Compensatory loss is determined separately; nominal or prospective relief must satisfy its own requirements. The existing unresolved question whether genuinely effective protection and unreasonable nonuse can provide a general complete defense is not presented for decision on this causation motion. The unappealed retaliatory-discharge dismissal remains effective.',
  'Harris preserves the objective-and-subjective environment test without an injury floor. Oncale, Faragher and Ellerth supply the actual-authority/material-aid requirement and preserve the distinct negligence route and existing complete-defense reservation.')])

rene_sep='''**Stone-Zsela, concurring.** He joins Parts I–III and the affirmance on the preserved contextual-inference ground. He would also hold that harassment imposed because a male employee is attracted to men is discrimination because of sex when his sex is a necessary component of that reason. Holding attraction constant, changing the employee's sex changes the disfavored relationship. Oncale's textual approach, in his view, warrants rejecting the categorical orientation exclusion itself rather than preserving only this claimant through an evidentiary inference. Sexual contact or common sex alone would still establish neither causation nor the complete claim.

His proposed construction would require proof of every objective and subjective hostile-environment element, actual employer attribution through material aid from delegated authority or separately proved negligence, and the conditions of each remedy. Harris would continue to permit liability without psychiatric injury or lost productivity; compensatory loss would require separate proof, and nominal or prospective relief its own legal conditions. The proposal concerns this statutory cause and does not create a separate stereotyping claim, compulsory comparator, general civility code or employer-wide decree. If adopted and applied, Harper would require the construction in all still-open direct-review claims within its scope, including earlier conduct; Reynoldsville would foreclose reliance alone as a selective exception while genuine limitations, attribution and remedial conditions continued to govern. Final judgments would remain closed and no new filing or collateral route would arise. Because the independent orientation question remains open in this case, he accepts the narrower Oncale ground as lawful and sufficient.

**Thomas, concurring in Part I and dissenting, joined by Scalia.** They would reverse the Ninth Circuit and restore summary judgment on causation. Their disagreement concerns the evidence, not categorical same-sex or orientation immunity. Oncale requires a supported inference that the conduct occurred because of the claimant's sex, and neither its sexual form nor its gravity supplies that inference by itself. Rene repeatedly attributed the abuse to being gay; in their view, comparing the touching to treatment of a woman adds a description of the acts rather than evidence of the coworkers' reason for selecting him. The other evidence does not bridge that gap.

They require neither sexual desire nor an actual female comparator and do not treat Rene's testimony as an irrebuttable legal concession. Nabozny involved separate discriminatory official responses and comparative treatment supporting sex causation; its equal-protection ruling does not make assault automatically discriminatory under Title VII. They would not create a new appellate stereotyping claim on the preservation record. The common causal rule remains intact, but they find the record insufficient under it and therefore oppose Parts II–III and the remand.'''

cases.append(dict(n=113,case='Rene v. MGM Grand Hotel, Inc.',inventory='Rene v. MGM Grand Hotel, Inc. +',date='2003-05-05',file='Rene-v-MGM-Grand-Hotel-Inc_merits_2003-05-05.md',dockets='Judgment below, 305 F.3d 1061 (en banc); no separate Supreme Court docket supplied',result='Affirmed and remanded, 7–2, on the hostile-environment claim; retaliation dismissal remains effective.',
event='Merits decision, May 5, 2003. On review of the Ninth Circuit\'s en banc judgment, 305 F.3d 1061, reversing employer summary judgment and remanding the hostile-environment claim. The question is whether the preserved sex-harassment record can establish discrimination because of sex despite Rene\'s attribution of the conduct to hostility toward his orientation. MGM seeks restoration of summary judgment; Rene seeks preservation of the remand.',
facts='Rene worked as a butler in an all-male unit from December 1993 through June 1996. His June 20, 1996 administrative charge alleged discrimination because of his male sex; his April 13, 1997 complaint alleged Title VII harassment. The preserved testimony describes the acts in Part II and repeated orientation explanations. The en banc court heard argument September 25, 2001 and issued judgment September 24, 2002. Its seven judgment votes included differing rationales; no Supreme Court merits alignment is imported from them. The retaliatory-discharge disposition was not appealed. No date of oral argument in this Court is supplied.',
stone='Stone proposes the broader necessarily sex-dependent orientation construction, but expressly accepts the contextual Oncale alternative if independent orientation coverage remains open. That legal trigger is satisfied: all eight reconciled Associates confine the preserved question to sex-causation evidence, and the record supplies no separately preserved independent claim. Stone therefore joins the full narrow majority and affirmance, with his broader statutory proposal and its qualifications retained in a concurrence. This uses his express alternative, not the standing fallback, and does not infer that losing a vote alone triggers a condition.',
compat='Part I commands all nine direct joins. Parts II–III command Stone plus the six frozen affirming Associates: Stevens, O\'Connor, Kennedy, Souter, Ginsburg and Breyer. O\'Connor\'s express causal-retention condition is answered by rejecting the circuit per se rule; Kennedy\'s preserved-claim condition is met without a new cause. Scalia and Thomas join Part I but maintain their contrary sufficiency application; no draft revision or inferred conversion is asserted. The strongest dissent is answered by identifying the combined evidence and the reasonable competing inference, not by treating any sexual touching as enough. Thomas\'s own Oncale opinion supports his lead of the substantive dissent, with Scalia joining. Stone\'s broader construction adds no controlling proposition. No Marks aggregation is used.',
judgment='**Affirmed and remanded, 7–2.**\n\n**Supporting:** '+R7+'.\n\n**Opposing:** Scalia and Thomas.\n\nThe Ninth Circuit\'s reversal of employer summary judgment stands on the contextual sex-causation ground. The hostile-environment claim returns for ordinary further proceedings under Parts I–III. The unappealed retaliatory-discharge dismissal remains effective.',
topology='__LEAD_AUTHOR__ delivers the opinion of the Court, joined in full by __LEAD_JOINERS__. Scalia and Thomas join Part I. Stone-Zsela files a concurring opinion. Thomas files an opinion concurring in Part I and dissenting, joined by Scalia.\n\n| Portion or writing | Direct coalition, including author | Relationship and scope |\n|---|---|---|\n| Lead, Part I | '+ROSTER+' | Common sex-causation rule and scope of preserved question. |\n| Lead, Parts II–III | '+R7+' | Contextual sufficiency, affirmance and remand. |\n| Stone-Zsela concurrence | Stone-Zsela | Joins the whole Court opinion; proposes broader orientation construction with complete liability and remedial qualifications. |\n| Thomas separate opinion | Thomas and Scalia | Joins Part I; opposes the sufficiency application and remand; would restore summary judgment. |',
holdings=rene_h,precedent='Oncale remains the governing same-sex and causal rule; the Court applies it to this contextual record and rejects the circuit lead\'s conclusive sexual-touching rationale. Harris retains its separate environment requirements without a psychiatric-injury floor. Brown v. Polk County preserves distinct possible causes at its own scope. Nabozny remains a distinct constitutional unequal-protection decision. Faragher and Ellerth continue to govern actual-authority attribution, separate negligence and the existing complete-defense reservation.',
law='A claimant\'s orientation explanation does not categorically defeat a preserved Title VII sex-harassment claim. Supported contextual evidence can permit sex causation even where that explanation is also present, while sexual form or gravity alone remains inconclusive. Rene\'s combined evidence satisfies Rule 56 on that issue; ultimate proof, employer attribution and relief proceed under the existing rules.',
separate=rene_sep,procedure='The case returns through the Ninth Circuit for ordinary further proceedings on the hostile-environment claim. Rene bears the required proof of cause, qualifying environment, employer responsibility and the predicates of relief; independently preserved grounds receive their ordinary procedural treatment.',
sources='Rene v. MGM Grand Hotel, Inc., 305 F.3d 1061 (9th Cir. 2002) (en banc). 42 U.S.C. §2000e-2(a)(1); Fed. R. Civ. P. 56. Oncale v. Sundowner Offshore Services, Inc., decided March 19, 1997; Harris v. Forklift Systems, Inc., 510 U.S. 17; Faragher v. City of Boca Raton, decided September 8, 1997; Burlington Industries, Inc. v. Ellerth, decided June 26, 1998. The account of harassment is evaluated in the posture of the employer\'s summary-judgment motion.',
negative='The independent orientation question is outside the framed and separately preserved claim, grounds (a) and (b), stated in Part I rather than as a disclaimer of the concurrence. The existing general complete-defense issue is outside this causation review, ground (a). The retaliation dismissal states surviving status (iii). Sexual form alone, the lack of a comparator requirement, and separate attribution and injury requirements are adopted operative limits answering actual arguments or avoiding a per se reading (iv). No automatic damages, trial, discovery, class remedy or liability disclaimer remains.',
source_map='Frozen C neutral and final reconciled sections establish the preserved claim, testimony, lower dates, unappealed claim and distinct appellate rationales. The reconciliation full-read verification covers sources/chunk9-c/rene-lower.txt. C Focused and C Rules supply Oncale, Harris, Faragher and Ellerth; C Prior Public supplies Brown and Nabozny at their separate scopes. The authorized May 5 review date and proper merits arrival are scheduling premises, not recovered historical grants.',
eligible=SEVEN,full=SEVEN,components=[dict(name='Hostile-environment appellate reversal affirmed and remanded',supporting=SEVEN,opposing=['Scalia','Thomas'])]))

harry_qual='''A transfer is hospital-directed movement outside its facilities, including discharge; movement after declaration of death and departure without permission of a hospital-affiliated person are excluded. Internal movement to intensive care is not a statutory transfer. For unstabilized transfer, §1395dd(c) requires either the individual's or legally responsible person's written request after explanation of the hospital's obligations and transfer risks, or a physician-signed certification, based on information then available, that expected medical benefits of treatment elsewhere outweigh increased transfer risks. If no physician is physically present in the emergency department, a qualified medical person may certify only after consulting a physician who makes that determination and later countersigns. Every certification must summarize supporting risks and benefits. Every route also requires available treatment minimizing risk; receiving space, qualified personnel and acceptance of appropriate treatment; all available emergency records, including the condition, observed signs or symptoms, preliminary diagnosis, treatment, test results, request or certification and the name and address of any required on-call physician who refused or failed timely to appear; qualified transport personnel and equipment with necessary appropriate life support; and applicable additional regulatory conditions. The transfer alternative is permissive, not a command to move every patient.

Section (b)(2) separately deems treatment compliance when the hospital offers the required examination and treatment, explains risks and benefits, the patient or representative refuses, and the hospital takes all reasonable steps to obtain written informed refusal. Section (b)(3) separately requires an offered transfer satisfying subsection (c), the risk-and-benefit explanation, refusal and all reasonable steps to obtain written informed refusal. These distinct alternatives retain their conditions. State medical law remains effective except to the extent it directly conflicts with an applicable federal duty under §1395dd(f).'''

harry_h='\n\n'.join([
h('I. The stabilization duty does not depend on actual transfer or discharge',
  'When a participating hospital determines that a person coming to it has an emergency medical condition, §1395dd(b)(1) requires the examination and treatment within available staff and facilities necessary for stabilization, or a transfer complying with subsection (c). Stabilization means preventing likely material deterioration, within reasonable medical probability, resulting from or during transfer; that medical measure does not add actual movement outside the hospital as a prerequisite to the duty.',
  'Part I of the opinion of the Court; all nine Justices directly join: '+ROSTER+'.',
  'In re Baby K already rejects the hospital\'s lack of an intended transfer as an excuse when an acute emergency and effective stabilizing capability are established. The statute offers stabilizing care or a compliant transfer; retaining the patient supplies no third option excusing both. Its transfer-related definition measures medical stability rather than postponing the obligation until departure. Roberts independently rejects an additional improper financial or other invidious motive requirement while preserving the enacted conditions.\n\nThe hospital argues that the estate\'s reading would federalize every negligent inpatient treatment decision. The argument does not justify the transfer prerequisite imposed below. The duty concerns an actually determined emergency, available stabilizing treatment and breach, with direct harm and causation required for this civil action. The estate alleges delay while Normil remained in emergency care before admission. Applying those bounded conditions to that phase gives effect to the statute without deciding every later course of inpatient treatment.',
  'In re Baby K is applied to reject the no-transfer prerequisite. Roberts preserves the statutory predicates while rejecting an extra improper-motive element. Their bounded emergency duty remains distinct from general medical negligence.',harry_qual),
h('II. Later admission cannot erase an accrued preadmission violation',
  'An alleged breach of an already-triggered stabilization duty during emergency care must be adjudicated even if the hospital later admits the patient; later admission cannot extinguish a completed earlier violation. The estate must prove by a preponderance an actual emergency determination, necessary treatment within available capability, breach and direct causal harm; §1395dd(d)(2)(A) permits a directly harmed person to seek the State\'s available personal-injury damages and appropriate equitable relief against the participating hospital within two years of the violation.',
  'Part II of the opinion of the Court; all nine Justices directly join.',
  'The complaint alleges a substantial delay in emergency care, a diagnostic notation involving pneumonia and possible sepsis, an unavailable scan required before admission, and ordered antibiotics allegedly not given. At dismissal these factual allegations receive their proper pleading effect. The notation and eventual death do not conclusively establish the statutory emergency determination, available treatment, breach or causal injury; those matters require ordinary adjudication under Part I.\n\nThe lower court must distinguish injury attributed to the preadmission phase from a claim resting solely on subsequent genuine inpatient care. The legal endpoint of an unperformed duty after bona fide admission remains open here because the character and timing of the actual admission and the alleged later breach have not been adjudicated; the present preadmission allegations independently defeat the categorical dismissal. This is a factual ground for leaving that distinct phase unresolved, not an admission exemption. The governing standard now supplied requires adjudication of the detected emergency, available stabilizing care, statutory performance and direct causal injury in the relevant phase. The private EMTALA action runs against the participating hospital. The separate screening dismissal and §1981 remand retain their existing status.',
  'In re Baby K supplies the duty tied to the detected emergency and medically defined stabilization. Roberts supplies the distinct direct-harm, hospital-action, remedial and limitations requirements. The automatic actual-transfer premise of the judgment below is rejected.')])

harry_sep='''**Stone-Zsela, concurring.** He joins the Court's no-transfer rule and reversal on the preadmission allegations. He would also hold that genuine inpatient admission itself cannot extinguish an already-triggered, unperformed stabilization duty. In his view, §1395dd(b) makes performance rather than location decisive: the hospital must stabilize the identified emergency through necessary available care, make a compliant transfer, or satisfy the applicable informed-refusal provision. Stability remains the medically bounded condition of reasonable probability, not guaranteed cure; an unknown condition or later unrelated deterioration after the duty ends would fall outside this proposed rule.

He relies on the statutory alternatives and Roberts's refusal to add an extra motive defense. He would reject Bryan's admission endpoint insofar as it terminates this unperformed duty, while retaining its distinction between EMTALA and general malpractice law. Baby K supplies neither a universal care entitlement nor a conclusive answer about every inpatient. The estate would still prove actual determination, necessary available care, breach and direct harm. The statutory hospital action and authorized remedies would remain separate from any action against individual clinicians, and the proposed rule would not establish a systemwide treatment failure from the pleaded course.

If adopted and applied, the construction would govern still-open direct-review claims within its scope under Harper, including earlier care. Reynoldsville would permit no reliance-only admission exception; genuine limitations, causation and remedy requirements would remain, and final judgments and time-barred claims would not reopen. With the admission endpoint left open on this record, he accepts the narrower ground: no actual transfer is required, and delayed admission cannot cure an earlier breach. The later phase should receive proper adjudication rather than a presumed absence of any preceding duty.'''

cases.append(dict(n=115,case='Harry v. Marchant',inventory='Harry v. Marchant +',date='2003-05-19',file='Harry-v-Marchant_merits_2003-05-19.md',dockets='Judgment below, 291 F.3d 767 (en banc); Eleventh Circuit No. 99-13205',result='Stabilization dismissal reversed and remanded, 9–0; separate screening dismissal and §1981 remand remain effective.',
event='Merits decision, May 19, 2003. On review of the Eleventh Circuit\'s en banc judgment, 291 F.3d 767. Review concerns whether EMTALA\'s stabilization duty can apply when an emergency patient is retained inside the hospital rather than transferred or discharged. The estate seeks reinstatement of its stabilization claim against Miami Beach Healthcare Group, Ltd., doing business as Aventura Hospital and Medical Center.',
facts='The complaint alleges that Lisa Normil arrived at the emergency room at approximately 1:17 a.m. on November 26, 1997. Dr. Marchant recorded pneumonia with sepsis to be ruled out and sought intensive-care admission. Dr. Coy refused admission pending a scan that could not be performed because isotopes were unavailable. After further delay Dr. Bazzi examined her and she entered intensive care; antibiotics were ordered but allegedly not administered. She died after respiratory and cardiac failure at approximately 12:45 p.m. Her movement was internal and she was not alleged to have left or been discharged. These are pleading allegations, not established medical findings. The en banc court reviewed stabilization alone, preserved screening dismissal and reinstated the panel\'s separate §1981 reversal; state claims were dismissed without prejudice and pursued separately. No oral-argument date in this Court is supplied.',
stone='The approved supplement proposes continuation of an unperformed detected-emergency duty through genuine admission, but expressly accepts preadmission reversal if the admission endpoint remains open. That trigger is met by the final reconciled ground: the pleading does not establish the timing and character necessary to decide the distinct solely-inpatient phase, while the earlier emergency delay independently requires adjudication. Stone joins the full common opinion and preserves his broader performance-based proposal in a qualified concurrence. No fallback is used. His actual-determination, available-care, breach, direct-harm and hospital-remedy limits are retained.',
compat='All eight frozen H1–H3 commitments directly join Parts I–II, including full statutory alternatives. Stone\'s express narrower alternative supports the same whole opinion. Each Associate joined Baby K\'s rejection of lack of intended transfer and Roberts\'s predicate distinctions; those actual prior joins supply the changed premise relative to the lower comparator. The admission endpoint is not declared settled by Baby K. Reservation rests on incomplete phase-specific facts under Engine §8(c), with remand separation and governing standards, not merely the fact that one ground independently suffices. No non-Stone commitment was revised after reconciliation. The hospital\'s federal-malpractice objection is answered by the actual emergency, capability, causation and remedy requirements.',
judgment='**Reversed and remanded, 9–0, on the hospital stabilization claim.**\n\n**Supporting:** '+ROSTER+'.\n\nThe actual-transfer ground for dismissal is rejected. Further proceedings must adjudicate the preadmission allegations under the stabilization duty and distinguish them from any claim resting solely on later genuine inpatient care. The separate screening dismissal and the §1981 remand remain effective.',
topology='__LEAD_AUTHOR__ delivers the opinion of the Court, joined in full by __LEAD_JOINERS__. All nine join Parts I–II. Stone-Zsela files a concurring opinion.',holdings=harry_h,
precedent='In re Baby K governs the rejection of a no-intended-transfer exemption and retains the complete transfer and informed-refusal alternatives. Roberts removes an extra improper-motive element while preserving actual statutory determination, breach, direct harm and the hospital-only civil-action requirements. The no-actual-transfer rule applied below cannot survive those authorities. State medical law retains effect except for a direct conflict with an applicable federal duty.',
law='Hospitals must meet the enacted stabilization or lawful-transfer duty after determining an emergency, even when retaining the patient. Later admission does not erase a completed emergency-care violation. The hospital\'s actual determination, available treatment, performance and direct causal harm govern the revived claim. The genuine-inpatient endpoint remains for a phase-specific case with the necessary facts; it does not defeat adjudication of the earlier violation here.',
separate=harry_sep,procedure='The case returns through the Eleventh Circuit. The lower court must determine the hospital\'s actual emergency determination, available stabilizing treatment, any lawful statutory alternative, the timing of any breach and resulting direct harm. It must separate the preadmission claim from any claim resting solely on later genuine inpatient care and apply the hospital-action, limitations and remedy requirements in Part II.',
sources='Harry v. Marchant, 291 F.3d 767 (11th Cir. 2002) (en banc), No. 99-13205. 42 U.S.C. §1395dd(b)–(f). In re Baby K, No. 93-1673, decided December 12, 1994; Roberts v. Galen of Virginia, Inc., No. 97-53, decided January 13, 1999. The medical course is alleged at the dismissal stage; the actual emergency determination, capabilities and causal consequences require adjudication.',
negative='The inpatient-duration question is expressly open under ground (c), identified phase-specific facts and governing remand standards; the record does not treat independence of preadmission reversal alone as permission to reserve it. Screening dismissal and §1981 remand state surviving status (iii). Internal movement, actual-transfer trigger, medical stability, distinct lawful alternatives and hospital-only action are adopted scope limits (iv), responding to the parties and needed for accurate statute operation. No automatic damages, cure, class decree or individual-clinician reassurance unrelated to the operative defendant rule was added.',
source_map='Frozen validated C neutral and final reconciliation establish the allegation/posture distinction and the full-source review of sources/chunk9-c/harry-en-banc.txt. C Baby K and the Roberts entry in C Focused supply the actual governing Supreme Court propositions, direct joins and complete exceptions. The neutral packet\'s original omission of Baby K is corrected in its frozen validation supplement. The May 19 merits event is an authorized scheduling premise; no later regulatory inpatient rule enters.',
eligible=ALL,full=ALL,components=[dict(name='Hospital stabilization dismissal reversed and remanded',supporting=ALL,opposing=[])]))

roe_qual='''Interference means restriction of a person's freedom of movement; intimidation means reasonable apprehension of bodily harm to oneself or another. Physical obstruction makes ingress or egress impassable or passage to or from the facility unreasonably difficult or hazardous. Reproductive services encompass medical, surgical, counseling and referral services concerning reproduction, pregnancy or termination, including carrying pregnancy to term, in hospitals, clinics, physicians' offices or other facilities. A facility includes the reproductive-service establishment and its building or structure. Requested treatment elsewhere for the alleged reproductive injury can fall within this definition.

For a private action under §248(a)(1), the claimant must be aggrieved by the prohibited conduct and involved in providing or seeking to provide, or obtaining or seeking to obtain, services in a reproductive-health facility. Each defendant's violation must be legally attributable to that defendant; shared belief, membership or another's independent act is insufficient. A parent or legal guardian is exempt from every FACE penalty and civil remedy for the described activity insofar as it is directed exclusively at that person's own minor. Section (d)(1) preserves First Amendment expression, including protected peaceful picketing and demonstrations. Section (d)(2) separately creates no new remedy for outside-facility interference with protected speech or religion, regardless of viewpoint, and limits no existing remedy. FACE remedies are nonexclusive, other state and local remedies are not preempted, and state and local regulation of reproductive services remains enforceable. Those independent provisions retain their distinct terms.'''

roe_h='\n\n'.join([
h('I. FACE applies to clinic personnel under its complete conduct and service-related predicates',
  'Section 248(a)(1) reaches any person, including clinic personnel, who by force, threat of force or physical obstruction intentionally injures, intimidates or interferes with a person, or attempts to do so, because that person is or has been obtaining or providing reproductive health services, or to intimidate that person, another person or a class from obtaining or providing them. Occupation and support for abortion supply no exemption; the prohibited means, intentional conduct and alternative service-related nexus must each be established.',
  'Part I of the opinion of the Court; all nine Justices directly join: '+ROSTER+'.',
  'American Life League applies the enacted access protection to defined conduct and preserves its intent, service connection and attribution requirements. Nothing in those provisions limits liability to outsiders or opponents of abortion. A patient seeking hospital treatment for reproductive injuries is seeking a covered kind of care, and intentionally restraining her may restrict access to it if the statutory nexus is present. The alleged request to stop the procedure and summon an ambulance thus matters to the statutory inquiry without establishing why the defendants restrained her.\n\nThe defendants\' treatment-quality objection is answered by the statute\'s actual conditions. A medical error, unwanted touch or restraint alone does not establish each element. If the actor\'s sole actual purpose is protective medical action and the required service-access cause or intimidating purpose is absent, the statutory claim fails. A protective label is not a separate immunity when the required intent and nexus are proved. The reported conditional concession about a solely protective purpose supplies no finding of the actual motive. Scheidler\'s refusal to add an economic motive absent from its statute cannot justify deleting FACE\'s express service nexus.',
  'American Life League is applied to the clinic-personnel setting with its definitions, attribution and statutory exclusions intact. National Organization for Women v. Scheidler, decided January 24, 1994, supplies the distinct rule against inventing an omitted statutory motive; FACE\'s expressed alternatives remain necessary.',roe_qual),
h('II. The amendment opportunity proceeds under ordinary pleading and the private-action conditions',
  'Roe receives the reasonable opportunity to amend directed below, with Rule 8 requiring fair notice of the intentional acts and their connection to obtaining or seeking the covered care rather than evidentiary proof in the complaint. Because this review is on the defendants\' petition and no cross-petition seeks improved pleading relief, the renewed-dismissal baseline with leave to amend remains effective.',
  'Part II of the opinion of the Court; all nine Justices directly join.',
  'Swierkiewicz distinguishes substantive proof from pleading, and Leatherman rejects a judge-made heightened pleading requirement beyond the governing Rules. Those decisions preserve the actual statutory elements. An amendment must give fair notice of the service-related connection instead of relying solely on the asserted injury, while the ultimate conduct, purpose, personal attribution and causal injury must be proved by a preponderance in ordinary merits proceedings.\n\nThe lower judgment directed renewed dismissal with a reasonable amendment opportunity. Roe seeks preservation of that judgment on the clinic defendants\' petition; without a cross-petition the Court cannot improve her pleading disposition by declaring the present complaint sufficient. The statutory private-action and relief conditions remain operative. Section 248(c)(1)(B) permits appropriate injunctive relief, compensatory and punitive damages, and costs and reasonable attorney and expert fees on their applicable conditions. Before final judgment an eligible plaintiff may elect five thousand dollars per attributable violation in place of actual compensatory damages; the election is permissive and replaces that category rather than every other remedy. The complete own-minor exception in Part I applies to all FACE relief.',
  'Swierkiewicz and Leatherman govern the distinction between notice pleading and proof. American Life League preserves attribution, private-action eligibility, the permissive statutory-damages election and the complete own-minor exception.'),
h('III. Public pseudonymity must protect substantial intimate privacy while preserving a fair defense',
  'Under Rules 10(a) and 26(c), a court may permit public pseudonymity when the substantial privacy interest in the intimate subject of a particular action outweighs the need for public identification and a tailored order preserves meaningful defense access. Roe\'s abortion and reproductive-injury allegations, coupled with her offer of necessary confidential identification to the defendants, warrant that limited protection while the proceedings and legal issues remain public.',
  'Part III of the opinion of the Court; all nine Justices directly join the procedural rule and application.',
  'Rule 10(a) makes public naming the ordinary practice, and openness must receive weight independently of the defendants\' need to investigate. Rule 26(c) permits fitted protection for sensitive information. This action necessarily exposes exceptionally intimate treatment and alleged injuries to reproductive organs. The plaintiff\'s identity contributes little to evaluating the statutory issue, while her offer of confidential identification permits access to medical records, investigation and a meaningful response.\n\nPrivate-party status and a demand for damages do not categorically defeat protection. Nor does the subject of abortion establish automatic anonymity. The decision rests on the particular disclosures and a practical means of protecting adversarial fairness. The lower court\'s refusal treated needed defense identification as a reason for public identification even though those purposes can be served separately. The district court must specify necessary recipients and filing protections, preserve access to nonidentifying legal and evidentiary material, and adjust disclosure upon a concrete showing of defense or public-access need. Blanket closure or concealment from the opposing parties would exceed this fitted protection. The governing basis is the Rules\' procedural accommodation; the general constitutional entitlement to anonymous civil litigation lies outside the question decided.',
  'The protective-order framework is applied to the particular intimate disclosure and defense needs. Lawall\'s distinct government-access and bypass holdings remain at their existing scope; the present holding rests on Rules 10(a) and 26(c).')])

cases.append(dict(n=116,case='Roe II v. Aware Woman Center for Choice, Inc.',inventory='Roe II v. Aware Woman Center for Choice, Inc. +',date='2003-06-02',file='Roe-II-v-Aware-Woman-Center-for-Choice-Inc_merits_2003-06-02.md',dockets='No. 01-777, under Aware Woman Center for Choice, Inc. v. Roe; judgment below, 253 F.3d 678; Eleventh Circuit No. 00-10231',result='Reviewed statutory/amendment and public-pseudonymity components affirmed, each 9–0; further proceedings under the preserved amendment and protective directions.',
event='Merits decision, June 2, 2003. On review of the Eleventh Circuit\'s judgment, 253 F.3d 678, on the clinic defendants\' petition, No. 01-777, captioned Aware Woman Center for Choice, Inc. v. Roe. The questions concern FACE\'s application to clinic personnel interfering with other reproductive treatment and public pseudonymity with necessary defense identification. The appellate judgment directed renewed dismissal with a reasonable opportunity to amend and reversed denial of public anonymity.',
facts='Roe alleges that clinic personnel forcibly restrained her after she demanded that an abortion stop and an ambulance take her elsewhere, causing serious internal injuries. Her actual purpose and theirs remain for adjudication. She offered to disclose her identity to the defendants as necessary for defense while seeking public pseudonymity. The lower opinion reports a conditional concession about a solely protective medical motive, not a finding that this motive actually governed the restraint. No cross-petition seeking better pleading relief is supplied. The review posture is a retained timely petition under the authorized scheduling premise, not revival of a denied petition. No oral-argument date in this Court is supplied.',
stone='Stone supports affirmation of the amendment opportunity and fitted public identity protection, actual FACE means/intent/nexus, personal attribution and causal proof, ordinary notice pleading and the cross-petition limit. The common Rules ground fully supports his pseudonym position. Lawall supplies an additional analogy in his approved reasoning but no new substantive privacy theory is necessary to his join; the opinion does not adopt a broader basis barred by Scalia or Thomas. His narrower alternative of further findings with interim protection is not triggered because the present record supports the definitive fitted order. No standing fallback is used.',
compat='All eight final P1–P3 commitments join the full opinion, including the common procedural P2 ground; Stone makes nine. The full statutory alternatives and facility/private-action condition avoid replacing the actual nexus with an anti-abortion belief or simple restraint test. Scalia and Thomas join Part III through procedural authority and individualized balance, without adopting Lawall\'s broader substantive informational-privacy premise. The six other Associates and Stone may accept the Lawall analogy without making it part of the nine-Justice rationale. That optional additional source creates no separate substantive proposal requiring publication. The current opinion preserves the preexisting damages election under its terms, without attributing to Stone a new join to American Life League\'s earlier general constitutional damages rationale. No material non-Stone revision or new factual premise follows.',
judgment='| Judgment component | Disposition and vote | Supporting Justices | Remedy |\n|---|---|---|---|\n| FACE coverage and amendment | Affirmed, 9–0 | '+ROSTER+' | Preserve renewed dismissal with a reasonable opportunity to amend under the complete statutory and ordinary pleading rules. |\n| Public pseudonymity | Affirmed, 9–0 | '+ROSTER+' | Permit public pseudonymity with necessary confidential defense identification and tailored protective administration. |\n\nIdentity protection continues while the district court implements the fitted order. More favorable pleading relief for Roe is unavailable on this petition without a proper cross-petition.',
topology='__LEAD_AUTHOR__ delivers the opinion of the Court, joined in full by __LEAD_JOINERS__. All nine join Parts I–III, with Part III resting on procedural authority and the particular privacy, openness and defense balance.',holdings=roe_h,
precedent='American Life League governs FACE\'s complete means, intentional conduct, alternative reproductive-service nexus, definitions, personal attribution, private-action conditions and separate statutory exclusions. Its rule applies to covered clinic-personnel conduct. Scheidler\'s omitted-motive rule does not erase FACE\'s express nexus. Swierkiewicz and Leatherman preserve ordinary notice pleading alongside ultimate substantive proof. Lawall remains a distinct ruling about confidential bypass administration and additional government access; this civil pseudonymity decision rests on the Rules.',
law='FACE protects the defined access to reproductive services against covered acts by clinic personnel as well as outsiders. The actual statutory cause or intimidating purpose distinguishes such interference from treatment error. Public pseudonymity is available on an individualized showing of substantial intimate privacy with meaningful defense access and continued public adjudication of the legal dispute.',
separate='',procedure='The district court must maintain public identity protection, specify who may receive identifying information for the defense, protect identifying filings while keeping legal and nonidentifying material public, and adjust access to demonstrated need. It must afford the reasonable amendment period directed below and assess the claim under Rule 8 and FACE\'s complete elements; subsequent merits proceedings determine actual conduct, motive, attribution and causal harm.',
sources='Roe v. Aware Woman Center for Choice, Inc., 253 F.3d 678 (11th Cir. 2001), No. 00-10231; review petition No. 01-777. 18 U.S.C. §248(a)(1), (c), (d), (e); Fed. R. Civ. P. 8, 10(a), 12, 26(c). American Life League v. Reno, decided November 13, 1995; Swierkiewicz v. Sorema N.A., decided February 26, 2002; Leatherman v. Tarrant County Narcotics Intelligence and Coordination Unit, decided March 3, 1993. The restraint, requests and injuries are allegations; the conditional protective-motive concession establishes no actual motive.',
negative='The cross-petition limit withholds enlarged pleading relief not available on this review and preserves the lower baseline (ii–iii). The general constitutional anonymity question is outside the procedural issue, ground (a). The medical-protection qualification, lack of occupation immunity, own-minor exception, distinct statutory construction provisions, permissive election and public/defense distinction are adopted limits required to state the actual rules (iv). Broad privacy immunity is omitted rather than disclaimed in the holdings. No medical-service injunction, automatic damages, constitutional malpractice or complete secrecy reassurance unnecessary to the actual rule was added.',
source_map='Frozen Roe Validated Neutral and Validated Supplement supply the petition identity, continuing controversy, lower judgment, allegations, cross-petition boundary and qualified concession. Final C reconciliation verifies the complete source at sources/chunk9-c/roe-ii-lower.txt. The complete official sources/chunk9-c/face-2001.txt was read in assembly for statutory alternatives and independent exceptions; C Focused supplies American Life League and pleading authority, and Lawall Public supplies the distinct prior topology and holdings. No later post-remand action is imported.',
eligible=ALL,full=ALL,components=[dict(name='FACE statutory coverage and reasonable amendment opportunity affirmed',supporting=ALL,opposing=[]),dict(name='Public pseudonymity with necessary defense disclosure affirmed',supporting=ALL,opposing=[])]))

BLOCKS=['Event','Participation','Public Action','Judgment & Remedy','Opinion Topology','Holdings','Precedent Treatment','Law After Decision','Separate Writings','Procedure After Action','Source Notes']
specs=[]
checks=[]
for c in cases:
    # Frozen text and approved position are copied mechanically, without retyping source passages.
    frozen=section(FINAL,c['n'])+'\n\n'+section(INITIAL,c['n'])
    approved=section(STONE,c['n'])
    form='Summary per curiam merits disposition on the supplied papers' if c.get('countable') is False else 'Signed lead opinion after authorized plenary merits review'
    chronology='The May 5, 2003 placement is historical for this event.' if c['n'] in (111,112) else 'The inventory supplies the review date and proper merits arrival as an authorized scheduling premise. No additional grant wording, filing, docket number or oral-argument date is reconstructed.'
    assignment='This summary per curiam action is not countable under Engine §8 and has no signed-lead assignment.' if c.get('countable') is False else '__ASSIGNMENT_BLOCK__'
    continuity=c['separate'] if c['separate'] else 'No material separate position is published. The common opinion fully resolves the recorded qualifications; historical authorship or a redundant separate writing is not imported.'
    public={
        'Event':c['event'], 'Participation':'All nine Justices participate.',
        'Public Action':('The Court vacates the judgment and remands by per curiam opinion.' if c.get('countable') is False else c['result']),
        'Judgment & Remedy':c['judgment'],'Opinion Topology':c['topology'],
        'Holdings':c['holdings'],'Precedent Treatment':c['precedent'],'Law After Decision':c['law'],
        'Separate Writings':c['separate'],'Procedure After Action':c['procedure'],'Source Notes':c['sources']}
    internal=f'''**Case and dockets:** {c['case']}; {c['dockets']}.
**Event and date:** {'Summary merits decision' if c.get('countable') is False else 'Merits decision'}; {c['date']}; October Term 2002, chunk 9, inventory item {c['n']}.
**Result:** {c['result']}
**Version / lineage:** Original decision.

## Event, chronology and factual posture

{c['event']}

{c['facts']}

{chronology}

## Participation, jurisdiction and entering law

All nine Justices participate at submission and decision: {ROSTER}. Nine participants supply a quorum and five votes suffice for a majority proposition. No case-specific nonparticipation is established. The supplied review vehicle is proper; its merits arrival is not reopened as a speculative certiorari question. Judgment and proposition joins are separately stated below.

**Research cutoff:** Immediately before {c['date']}. Same-day matters use the common entering baseline unless an effective decision is actually supplied; later scheduled or committed events do not supply substantive law here. Earlier Supreme Court law is taken from the authorized doctrinal reading copies, not from a historical lower opinion's different description of it.

**Entering-law and source map:** {c['source_map']}

The historical comparator is used only through the final frozen reconciliation. Published source recitations and the expressly authorized scheduling premise support this bounded decision under Engine §14. No missing research material establishes a filing default, unproved fact or lost litigant opportunity. No original filing not recovered is represented as read.

## Stone's approved position and final compatibility

{c['stone']}

### Mechanically preserved approved supplement

{approved}

## Opinion form and final joins

**Form selected before assignment:** {form}. Its scope and form rest on the actual questions, record and coalition, not on authorship counts.

{c['compat']}

{c['topology']}

## Assignment

{assignment}

## Judgment, remedy and stage

{c['judgment']}

{c['procedure']}

## Controlling holdings

{c['holdings']}

## Current-law effect and precedent status

{c['precedent']}

{c['law']}

## Published noncontrolling positions and continuity

{continuity}

Any separate proposal just stated is noncontrolling at this event's date. No new roster, allotment or Court practice follows. The mandated lower-court proceedings are the case's postdecision stage; they do not leave the Supreme Court merits event incomplete. No additional connected external event or later historical consequence is admitted.

## Frozen commitments and historical reconciliation

The following case-specific passages are copied mechanically from `../freeze/OT_2002CHUNK9_C_RECONCILED.md`. Its final matrix and express revisions govern over provisional wording; the initial analysis is preserved for audit. No fresh non-Stone commitment is inferred from Stone's position.

{frozen}

## Validation annex

**Final legal compatibility:** {c['compat']}

**Engine §8 negative-statement audit:** The Judgment & Remedy, Holdings, Precedent Treatment, Law After Decision and Procedure After Action blocks were reviewed individually. {c['negative']}

**Deterministic draft checks:** Exactly eleven ordered Public Projection blocks; each internal controlling-holdings body is copied unchanged to its public Holdings block; the explicit component arrays cover all nine participants without overlap; each authored controlling explanation is at most 350 words. The builder asserts these conditions before writing. No final assignment tally or final lead author is selected in this draft. Serial assignment, final publication and term-wide tooling remain integration tasks, not completed validations claimed here.

**Draft validation status:** Assembly draft for serial integration. Structural checks above passed; independent review, serial assignment, publication and term-wide verification remain pending. Intended durable location: `../records/{c['file']}`. No state tracker or completed adjudication is modified by this draft.

## Public Projection

'''
    projection='\n\n'.join('## '+b+'\n\n'+public[b] for b in BLOCKS).rstrip()+'\n'
    record=internal+projection
    assert record.split('## Controlling holdings\n\n',1)[1].split('\n\n## Current-law',1)[0] == public['Holdings']
    assert re.findall(r'^## (.+)$',projection,re.M)==BLOCKS
    assert record.count('__ASSIGNMENT_BLOCK__')==(0 if c.get('countable') is False else 1)
    for comp in c['components']:
        voters=comp['supporting']+comp['opposing']+comp.get('not_reached',[])
        assert len(voters)==len(set(voters))==9 and set(voters)==set(ALL)
    (OUT/c['file']).write_text(record,encoding='utf-8',newline='\n')
    spec=dict(case=c.get('inventory',c['case']),date=c['date'],file=c['file'],eligible_authors=c['eligible'],full_joiners=c['full'],assigner='' if c.get('countable') is False else 'Stone-Zsela',components=c['components'])
    if c.get('countable') is False: spec['countable']=False
    specs.append(spec)
    checks.append({'file':c['file'],'public_blocks':len(BLOCKS),'holdings_identity':True,'components_complete':True,'ordinary_explanations_within_350':True,'assignment_placeholders':record.count('__ASSIGNMENT_BLOCK__')})
(OUT/'C_specs.json').write_text(json.dumps(specs,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
(OUT/'C_draft_checks.json').write_text(json.dumps(checks,indent=2)+'\n',encoding='utf-8')
print(json.dumps(checks,indent=2))
